<?php
declare(strict_types=1);namespace App\Tests\Imperium\Runtime;use App\Bootstrap\CanonicalJson;use App\Imperium\Runtime\Senate\{ModelBoundProfileReconciliationService,ModelBoundProfileDispositionAuthorityOpeningService,ProfileExaminationReconciliationCognitionGateway};use PHPUnit\Framework\TestCase;
final class ModelBoundProfileReconciliationFlowTest extends TestCase
{
 public function testReconcilesWithoutAggregationThenOpensOnlyDispositionAuthority():void{$root=sys_get_temp_dir().'/imperium-reconcile-'.bin2hex(random_bytes(5));try{[$opening,$authority,$lord]=$this->fixtures($root);$g=new class implements ProfileExaminationReconciliationCognitionGateway{public function reconcile(array$a,array$f):array{return['agreements'=>['All cite sealed evidence.'],'attribution_treatment'=>['Attributions preserved.'],'disagreements'=>['Security blocks while peers pass.'],'finding_references'=>$a['available_finding_references'],'limitations'=>[],'rationale'=>'Preserve findings and blocking dissent.','severity_treatment'=>['Security HIGH remains binding.'],'uncertainties'=>[]];}};$r=(new ModelBoundProfileReconciliationService($root,$g))->reconcile($opening,$authority);self::assertSame('PROFILE_EXAMINATION_FINDINGS_RECONCILED_PENDING_DISPOSITION_AUTHORITY_OPENING',$r['status']);self::assertFalse($r['vote_authority']);self::assertTrue($r['mandatory_security_blocking_condition']);$a=$r['disposition_phase_opening_authority']['authority_id'];$o=(new ModelBoundProfileDispositionAuthorityOpeningService($root))->open($r['reconciliation_id'],$a,$lord);self::assertSame('PROFILE_EXAMINATION_DISPOSITION_AUTHORITY_OPENED_PENDING_LORD_SPEAKER_DISPOSITION',$o['status']);self::assertTrue($o['senate_disposition_authority']);self::assertNull($o['disposition']);self::assertTrue($o['disposition_authority']['security_block_must_be_preserved']);self::assertFalse($o['profile_approval_authority']);}finally{$this->remove($root);}}
 private function fixtures(string$root):array{$find=[];foreach(['trust','security','usability']as$j){$id='model-bound-profile-senator-finding-'.substr(hash('sha256',$j),0,20);$sec='security'===$j;$f=$this->rec(['finding_id'=>$id,'jurisdiction'=>$j,'decision'=>['attributed_defect'=>$sec?'access_restrictions':null,'disposition'=>$sec?'FAIL':'PASS','severity'=>$sec?'HIGH':'NONE'],'mandatory_security_blocking_condition'=>$sec,'senator_finding_authority_consumed'=>true,'deliberation_open'=>false]);$this->write($root.'/var/imperium/offices/senate/model-bound-profile-senator-findings/'.$id.'.json',$f);$find[]=['jurisdiction'=>$j,'finding_id'=>$id,'finding_digest'=>$f['record_digest'],'decision'=>$f['decision'],'mandatory_security_blocking_condition'=>$sec];}$auth='model-bound-profile-reconciliation-authority-'.str_repeat('a',20);$id='model-bound-profile-deliberation-opening-'.str_repeat('b',20);$o=$this->rec(['instance_id'=>'test','case_id'=>'case','case_digest'=>'digest','subject_profile'=>['profile_id'=>'p'],'admitted_findings'=>$find,'mandatory_security_blocking_condition'=>true,'reconciliation_authority'=>['authority_id'=>$auth,'authority_single_use'=>true],'status'=>'PROFILE_EXAMINATION_DELIBERATION_OPENED_PENDING_RECONCILIATION','deliberation_open'=>true,'reconciliation_authority_exercisable'=>true,'vote_authority'=>false,'aggregation_authority'=>false,'senate_disposition_authority'=>false]);$this->write($root.'/var/imperium/offices/senate/model-bound-profile-deliberation-openings/'.$id.'.json',$o);$lord='binding-lord';$this->write($root.'/var/imperium/offices/senate/occupancy/'.$lord.'.json',$this->rec(['instance_id'=>'test','seat'=>'senate.lord-speaker','manifestation_id'=>'lord','occupancy_generation'=>1,'status'=>'ACTIVE','binding_atomic'=>true,'profile_examination_disposition_phase_opening_authority'=>true,'execution_authority'=>false]));return[$id,$auth,$lord];}
 private function rec(array$r):array{$r['record_digest']=hash('sha256',CanonicalJson::encode($r));return$r;}private function write($p,$r):void{if(!is_dir(dirname($p)))mkdir(dirname($p),0770,true);file_put_contents($p,json_encode($r));}private function remove($p):void{if(!is_dir($p))return;foreach(array_diff(scandir($p),['.','..'])as$e){$c=$p.'/'.$e;is_dir($c)?$this->remove($c):unlink($c);}rmdir($p);}
}
